L000334	\section{Derivation of Flight size PDF solution}
L000335	
L000336	We consider a colloid that is moving between pores of different length $\lambda$. We assume that the length and the diameter are the same. That is, a long pore has also a large diameter. If the colloid enters the pore at a distance $R_c$ from the wall it dives. The probability that the colloid does not dive, that is, that is flies upon entering a pore is denoted by $\alpha_i$. The latter can depend on the properties of the pore, like its length and diameter. The probability $p_n$ that a particle flies exactly along $n$ pores before it dives is given by
L000337	
L000338	\begin{align}
L000339	\label{eq:pn}
L000340	p_n = \prod\limits_{i = 1}^n \alpha_i (1 - \alpha_{n+1}),
L000341	\end{align}
L000342	
L000343	that is, the probability to fly along $n$ pores times the probability to dive at the $n+1$th pore. Thus, the distribution of flight lengths is given by
L000344	
L000345	\begin{align}
L000346	\label{eq:p}
L000347	p(x) = \left\langle \sum\limits_{n = 0}^\infty \rho_n(x) p_n \right\rangle,
L000348	\end{align}
L000349	
L000350	where $\rho_n(x)$ is the distribution of flight distances after $n$ steps,
L000351	
L000352	\begin{align}
L000353	\rho_n (x) = \delta(x - \ell_n).
L000354	\end{align}
L000355	
L000356	The flight distance $\ell_n$ after $n$ pores is
L000357	
L000358	\begin{align}
L000359	\label{eq:ell}
L000360	\ell_n = \sum\limits_{i = 1}^n \lambda_i.
L000361	\end{align}
L000362	
L000363	The angular brackets denote the average over all colloids. We can write $p(x)$ by using~\eqref{eq:pn} and~\eqref{eq:ell} as
L000364	
L000365	\begin{align}
L000366	p(x) = \left\langle \sum\limits_{n = 0}^\infty \delta\left(x - \sum\limits_{i = 1}^n \lambda_i\right) \prod\limits_{i = 1}^n \alpha_i
L000367	(1 - \alpha_{n+1}) \right\rangle
L000368	\end{align}
L000369	
L000370	\subsection{Constant diving rate and constant pore-length}
L000371	
L000372	We consider the first the case of constant diving rate $\alpha_0$ and pore length $\lambda_0$. Thus, we obtain for $p(x)$
L000373	
L000374	\begin{align}
L000375	p(x) = \sum\limits_{n = 0}^\infty \delta\left(x  - n \lambda_0\right) \alpha_0^n
L000376	(1 - \alpha_0).
L000377	\end{align}
L000378	
L000379	That is, the probability $p_n$ of $x = n \lambda_0$ is
L000380	
L000381	\begin{align}
L000382	p_n = \alpha_0^n (1 - \alpha_0) = \exp(n \ln \alpha_0) - \exp[(n + 1) \ln
L000383	\alpha_0] = \exp(- x_n/\lambda_c) - \exp(-x_{n+1}/\lambda_c) = H(x_n > \lambda_0),
L000384	\end{align}
L000385	
L000386	where we defined $\lambda_c = - \lambda_0/\ln \alpha_0$ For $x \gg \lambda_c$, we can write
L000387	
L000388	\begin{align}
L000389	p_n = \frac{\Delta x \exp(-x/\lambda_c)}{\lambda_c},
L000390	\end{align}
L000391	
L000392	that is
L000393	
L000394	\begin{align}
L000395	p(x) = \frac{p_n}{\Delta x} = \frac{\exp(-x/\lambda_c)}{\lambda_c}.
L000396	\end{align}
L000397	
L000398	Thus, it decays exponentially fast on the length scale $\lambda_c = - \lambda_0/\ln \alpha_0$.
L000399	
L000400	\begin{figure}
L000401	\includegraphics[width=0.8\textwidth]{S2_flightPDF_lambda_constant.pdf}
L000402	\caption{Distribution of flight distances for constant pore length and diving rate.\label{fig1}}
L000403	\end{figure}
L000404	
L000405	\subsection{Constant diving rate and exponential pore-length distribution}
L000406	
L000407	We consider the case the $\alpha_i = \alpha_0 = $ constant and $\lambda_i$ exponentially distributed with characteristic scale $\ell_0$. In this case,
L000408	
L000409	\begin{align}
L000410	\rho_n(x) = \left(\frac{x}{\ell_0}\right)^{n-1}
L000411	\frac{\exp(-x/\ell_0)}{\Gamma(n) \ell_0}.
L000412	\end{align}
L000413	
L000414	for $n > 0$. Thus, we obtain for the flight distance distribution
L000415	
L000416	\begin{align}
L000417	p(x) = \frac{\exp(-x/\ell_0)}{\ell_0}(1 - \alpha_{0})  \sum\limits_{n =
L000418	  1}^\infty \left(\frac{x}{\ell_0}\right)^{n-1}
L000419	\frac{\alpha_0^{n}}{\Gamma(n)} + (1 - \alpha_0) \delta(x)
L000420	\end{align}
L000421	
L000422	The sum can be written as
L000423	
L000424	\begin{align}
L000425	& \sum\limits_{n = 1}^\infty \left(\frac{x}{\ell_0}\right)^{n-1}
L000426	\frac{\alpha_0^{n}}{\Gamma(n)} = \left(\frac{x}{\ell_0}\right)^{-1} \sum\limits_{n =
L000427	  1}^\infty \left(\frac{x}{\ell_0}\right)^{n}
L000428	\frac{\alpha_0^{n}}{\Gamma(n)}
L000429	\\
L000430	&= \left(\frac{x}{\ell_0}\right)^{-1} \left[\sum\limits_{n =
L000431	  0}^\infty \left(\frac{x}{\ell_0}\right)^{n}
L000432	\frac{\alpha_0^{n}}{\Gamma(n)} - 1\right] = \left(\frac{x}{\ell_0}\right)^{-1} \left[\exp(x\alpha_0/\ell_0) - 1\right]
L000433	\end{align}
L000434	
L000435	Thus, we obtain for $p(x)$
L000436	
L000437	\begin{align}
L000438	p(x) = \frac{(1 - \alpha_{0})\exp(- x(1 - \alpha_0)/\ell_0)}{\ell_0}
L000439	\left(\frac{x}{\ell_0}\right)^{-1} \left[1 - \exp(-x \alpha_0/\ell_0)\right]
L000440	+ (1 - \alpha_0) \delta(x)
L000441	\end{align}
L000442	
L000443	The characteristic decay distance here is $\ell_0/(1 - \alpha)$ after which $p(x)$ decays exponentially with distance. For $\ell_0 \ll x \ll \ell_0/(1 - \alpha_0)$ it decays as $x^{-1}$.
L000444	
L000445	\subsection{Variable diving rate and Gamma-distributed pore lengths}
L000446	
L000447	The probability for diving
L000448	
L000449	\begin{align}
L000450	\beta(\lambda) = \frac{\pi (\lambda/2)^2 - \pi (\lambda/2-R_c)^2}{\pi (\lambda/2)^2}
L000451	H(\lambda/2 - R_c) + H(R_c - \lambda/2).
L000452	\end{align}
L000453	
L000454	The probability that the colloid does not dive is then accordingly
L000455	
L000456	\begin{align}
L000457	\alpha(\lambda) = 1 - \beta = (1-2 R_c/\lambda)^2
L000458	H(\lambda/2 - R_c)  - H(R_c - \lambda/2)
L000459	\end{align}
L000460	
L000461	In this case, we obtain for the distribution of flight lengths
L000462	
L000463	\begin{align}
L000464	p(x) = \left\langle \sum\limits_{n = 0}^\infty \delta\left(x - \sum\limits_{i = 1}^n \lambda_i\right) \prod\limits_{i = 1}^n (1-2 R_c/\lambda_i)^2
L000465	[1 - (1-2 R_c/\lambda_{n+1})^2] \right\rangle
L000466	\end{align}
L000467	
L000468	where we assume that all pore radii are larger than the critical radius. We consider now the Laplace transform in $x$ to obtain
L000469	
L000470	\begin{align}
L000471	\widetilde p(k) &= \left\langle \sum\limits_{n = 0}^\infty \exp\left(- k \sum\limits_{i = 1}^n \lambda_i\right) \prod\limits_{i = 1}^n \alpha(\lambda_i)
L000472	[1 - \alpha(\lambda_{n+1})] \right\rangle
L000473	\nonumber\\
L000474	&= \left\langle \sum\limits_{n = 0}^\infty \prod\limits_{i = 1}^n \exp\left(- k \lambda_i\right)  \alpha(\lambda_i)
L000475	[1 - \alpha(\lambda_{n+1})] \right\rangle
L000476	\nonumber\\
L000477	&= \sum\limits_{n = 0}^\infty \prod\limits_{i = 1}^n \left\langle \exp\left(- k
L000478	\lambda_i\right) \alpha(\lambda_i) \right\rangle
L000479	\left\langle [1 - \alpha(\lambda_{n+1})] \right\rangle
L000480	\nonumber\\
L000481	&= \sum\limits_{n = 0}^\infty \left\langle \exp\left(- k
L000482	\lambda\right) \alpha(\lambda) \right\rangle^n
L000483	\left\langle [1 - \alpha(\lambda)] \right\rangle
L000484	\nonumber\\
L000485	&= \frac{\left\langle [1 - \alpha(\lambda)] \right\rangle}{1 - \left\langle \exp\left(- k
L000486	\lambda\right)  \alpha(\lambda)\right\rangle}
L000487	\end{align}
L000488	
L000489	We need to determine
L000490	
L000491	\begin{align}
L000492	F(k)&\equiv \left\langle \exp\left(- k \lambda\right)  \alpha(\lambda)\right\rangle =
L000493	\int\limits_{0}^\infty d y p_\lambda(y) \exp\left(- k y\right)  \alpha(y)
L000494	\end{align}
L000495	
L000496	in order to understand the $k$-dependence of $\widetilde p(k)$. The pore length distribution $p_\lambda(y)$ is given by the Gamma distribution,
L000497	
L000498	\begin{align}
L000499	\label{eq:gamma}
L000500	p_\lambda(y) = \left(\frac{y}{\ell_0}\right)^{\beta-1}
L000501	\frac{\exp(-y/\ell_0)}{\Gamma(\beta) \ell_0}.
L000502	\end{align}
L000503	
L000504	Thus, we obtain for $F(k)$
L000505	
L000506	\begin{align}
L000507	F(k) & =
L000508	\int\limits_{0}^\infty d y \left(\frac{y}{\ell_0}\right)^{\beta-1}
L000509	\frac{\exp(-y/\ell_0)}{\Gamma(\beta) \ell_0} \exp\left(- k y\right)
L000510	\alpha(y)
L000511	=
L000512	\int\limits_{0}^\infty d y \left(\frac{y}{\ell_0}\right)^{\beta-1}
L000513	\frac{\exp[-y (k + 1/\ell_0]}{\Gamma(\beta) \ell_0}  \alpha(y),
L000514	\end{align}
L000515	
L000516	where $\beta = 0.4$.  This shows that $F(k) = G(k+1/\ell_0)$, that is, it is a function of $k+1/\ell_0$. This implies that $p(x)$ decays exponentially fast for $x > \ell_0$. Figure~\ref{fig} shows the distribution of flight distances for the Gamma distribution~\ref{eq:gamma} with $\beta = 0.4$ and $\ell_0 = 1$.
